// generar_303_examenes_a_historial_y_emoji_enfermedades.js
// CHIQUI Entre Señales — Reorganización de Historial médico + emoji enfermedades
//
// Tres ajustes en la página de Salud:
//
// 1. EXÁMENES DE LABORATORIO (los de valores: hemograma, bioquímico)
//    se mueven de "Signos vitales" a "Historial médico", que es donde
//    corresponden. Quedan justo debajo de "Visitas veterinarias".
//
// 2. La sección de exámenes que se SUBEN COMO PDF/IMAGEN pasa a
//    llamarse "Documentos de examen" (antes solo "Exámenes"), para
//    distinguirla claramente de los exámenes de laboratorio con
//    valores. El modal correspondiente ahora dice "Nuevo documento de
//    examen".
//
// 3. El emoji de "Enfermedades" cambia de 🏥 (hospital) a 🦠 (microbio),
//    porque el hospital chocaba con el de "Visitas veterinarias". Ahora
//    cada sección tiene su emoji propio.
//
// Orden final de Historial médico:
//   Visitas veterinarias → Exámenes de laboratorio → Documentos de
//   examen → Enfermedades → Observaciones.
//
// No hay SQL.
//
// Uso:
//   node generar_303_examenes_a_historial_y_emoji_enfermedades.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/prevencion/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
